/* Write n bytes from src into the buffer starting at start with wrap-around.
 * Returns actual bytes written. Does NOT bump rb->count — caller does that. */
static size_t drain_to_tail(ringbuf_t *rb, const uint8_t *src, size_t n,
                             size_t start) {
    size_t remaining = n;
    size_t pos = start;

    while (remaining > 0) {
        /* Write until we hit the end of the backing store */
        size_t chunk = rb->capacity - pos;
        if (chunk > remaining)
            chunk = remaining;
        memcpy(rb->data + pos, src, chunk);
        pos += chunk;
        if (pos == rb->capacity)
            pos = 0;
        src += chunk;
        remaining -= chunk;
    }

    return n - remaining;
}

