    if (!rb || !data || len == 0)
        return 0;

    for (size_t written = 0; written < len;) {
        if (rb->count >= rb->capacity)
            break; /* full */

        /* Available contiguous space before tail overwrites head */
        size_t avail = rb->capacity - rb->count;
        size_to_copy = rb->capacity - rb->tail; /* up to end of array */
        if (avail < to_cap)
            to_cap = avail;
        drain_to_tail(rb, data + written, to_cap, rb->tail);
        rb->tail = (rb->tail + to_cap) % rb->capacity;
        rb->count += to_cap;
        written += to_cap;
    }

    return written;
}

