int main(void) {
    int ok = 1;
    uint8_t buf[256];
    size_t r;

    /* test rb_create / rb_capacity / rb_destroy */
    {
        ringbuf_t *rb = rb_create(4);
        if (!rb) { printf("FAIL: create null\n"); ok = 0; }
        if (r = rb_capacity(rb), r != 4) { printf("FAIL: capacity %zu != 4\n", r); ok = 0; }
        rb_destroy(rb);
    }

    /* test NULL safety */
    {
        if (rb_create(0)) { printf("FAIL: create(0)\n"); ok = 0; }
        if (rb_write(NULL, buf, 4) != 0) { ok = 0; }
        if (rb_read(NULL, buf, 4) != 0) { ok = 0; }
        if (rb_peek(NULL, buf, 4) != 0) { ok = 0; }
        if (rb_size(NULL) != 0) { ok = 0; }
        if (rb_capacity(NULL) != 0) { ok = 0; }
        if (rb_clear(NULL), 0) { /* just check it doesn't crash */ }
        rb_destroy(NULL); /* should not crash */
    }

    /* test write/read round-trip */
    { ringbuf_t *rb = rb_create(8); unsigned int i;
      for (i = 0; i < 256; i++) buf[i] = (uint8_t)i;
      r = rb_write(rb, buf, 256);
      if (r != 8) { printf("FAIL: wrote %zu not 8\n", r); ok = 0; }
      r = rb_size(rb);
      if (r != 8) { printf("FAIL: size %zu\n", r); ok = 0; }
    }

    /* test wrap-around */
    return ok ? 0 : 1;
}

